#include <forward_list>
#include <iostream>
#include <string>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 100) return 1;
    std::forward_list<std::string> words;
    for (int i = 0; i < n; i++) {
        std::string word;
        if (!(std::cin >> word)) return 1;
        if (word.size() < 1 || word.size() > 20) return 1;
        words.push_front(word);
    }
    std::cout << words.front() << std::endl;
    return 0;
}
